// Package symbols holds the yaegi symbol tables of the Go guest's import allowlist (internal/goallow).
//
// The per-package files are generated by `make symbols` (yaegi extract, run for GOOS=wasip1 GOARCH=wasm with
// the pinned toolchain); only the packages listed there are linked into the guest. This file is the
// hand-written registry they populate.
package symbols

import (
	"encoding/json"
	"fmt"
	"reflect"
)

// Symbols maps "<import path>/<package name>" to the exported symbols of that package, in the shape
// interp.Interpreter.Use expects.
//
//nolint:gochecknoglobals // populated by the generated init functions of this package, yaegi's registry shape
var Symbols = map[string]map[string]reflect.Value{}

// mapTypes lists the interfaces yaegi must expose on interpreted values passed to these functions, so that
// interpreted types implementing fmt.Stringer, error, json.Marshaler, ... behave as in compiled Go.
//
//nolint:gochecknoglobals // read once by init below; package-level to mirror yaegi's stdlib registry
var mapTypes = map[reflect.Value][]reflect.Type{}

func init() { //nolint:gochecknoinits // registry setup in yaegi's shape, run when the guest package is linked
	formatters := []reflect.Type{
		reflect.TypeFor[fmt.Formatter](),
		reflect.TypeFor[fmt.Stringer](),
	}
	for _, fn := range []any{
		fmt.Errorf, fmt.Fprint, fmt.Fprintf, fmt.Fprintln, fmt.Sprint, fmt.Sprintf, fmt.Sprintln,
		fmt.Append, fmt.Appendf, fmt.Appendln,
		// yaegi redirects these to the plugin's stdout and copies their mapping; they are only referenced here.
		fmt.Print, fmt.Printf, fmt.Println, //nolint:forbidigo // referenced as map keys, never called
	} {
		mapTypes[reflect.ValueOf(fn)] = formatters
	}

	mapTypes[reflect.ValueOf(json.Marshal)] = []reflect.Type{reflect.TypeFor[json.Marshaler]()}
	mapTypes[reflect.ValueOf(json.MarshalIndent)] = []reflect.Type{reflect.TypeFor[json.Marshaler]()}
	mapTypes[reflect.ValueOf(json.Unmarshal)] = []reflect.Type{reflect.TypeFor[json.Unmarshaler]()}

	Symbols["."] = map[string]reflect.Value{"MapTypes": reflect.ValueOf(mapTypes)}
}
